var path = "Assets/Resources/UI/SaveSlotPanel.prefab";
var root = PrefabUtility.LoadPrefabContents(path);
if (root == null) return "LOAD FAILED: " + path;
var sb = new System.Text.StringBuilder();
var targets = new Dictionary<string, Vector2>();
targets["Slot 1"] = new Vector2(180f, -243f);
targets["Slot 2"] = new Vector2(180f, -433f);
targets["Slot 3"] = new Vector2(180f, -623f);
int changed = 0;
foreach (var rt in root.GetComponentsInChildren<RectTransform>(true))
{
    if (!targets.ContainsKey(rt.name)) continue;
    Vector2 want = targets[rt.name];
    sb.Append(rt.name).Append(": ").Append(rt.anchoredPosition.x).Append(",").Append(rt.anchoredPosition.y)
      .Append(" -> ").Append(want.x).Append(",").Append(want.y).Append("\n");
    rt.anchoredPosition = want;
    changed++;
}
if (changed != 3) { PrefabUtility.UnloadPrefabContents(root); return "ABORT: matched " + changed + " slots"; }
PrefabUtility.SaveAsPrefabAsset(root, path);
PrefabUtility.UnloadPrefabContents(root);
AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return sb.ToString() + "SAVED " + path;
